insert into public.posts (slug, username, title, description, aesthetic, difficulty, hours, kind, color, trim_color, tools, materials, steps, image_path, image_width, image_height, likes, avatar, created_at) values
  ('mock-neck-mini', 'stitchbyren', 'A jersey maxi, cut down to a mock-neck mini', 'Shorten a stretchy maxi dress and reuse the cut-off fabric for a clean mock-neck collar.', 'Y2K', 'Beginner', 1.5, 'dress', '#1f2326', '#1f2326', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Jersey maxi dress', 'Twin needle', 'Stretch thread']::text[], array['Try on and mark the mini length, adding 2 cm for the hem.', 'Cut a collar strip from the removed fabric, fold it in half, and stitch it to the neckline.', 'Hem the skirt with a twin needle or a narrow zigzag so it still stretches.']::text[], '/explore/photos/mock-neck-mini.jpg', 400, 545, 905, 0, '2026-10-01T12:00:00.000Z'),
  ('lace-plunge-top', 'noor.sews', 'Slip lace + a ribbed tank = this top', 'Crop a plain ribbed tank and give it a deep lace plunge salvaged from an old slip.', 'Y2K', 'Beginner', 1.5, 'cami', '#1c1c1f', '#2d2a2a', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Ribbed tank', 'Lace from an old slip', 'Ballpoint needle']::text[], array['Try on the tank and mark a deep V neckline and a cropped hem.', 'Pin the slip lace over the V with a 2 cm overlap, then zigzag it in place.', 'Trim the tank fabric behind the lace and fold up a stretch-stitched hem.']::text[], '/explore/photos/lace-plunge-top.jpg', 400, 598, 688, 1, '2026-10-01T11:00:00.000Z'),
  ('off-shoulder-stripe', 'the.mending.club', 'A men’s striped shirt, worn off the shoulder', 'Rework the collar of an oversized striped shirt into a wide fold-over neckline that sits off one shoulder.', 'Minimalist', 'Intermediate', 3, 'shirt', '#f3f4f6', '#4a5260', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Striped button-up', 'Snap fastener', 'Matching thread']::text[], array['Remove the collar and mark a wide scoop that slides off one shoulder.', 'Cut a long facing from the shirt tail and turn it into a deep fold-over band.', 'Sew the band around the new neckline and add a hidden snap at the front.']::text[], '/explore/photos/off-shoulder-stripe.jpg', 400, 377, 965, 2, '2026-10-01T10:00:00.000Z'),
  ('redyed-black-jeans', 'luca.loop', 'Faded black jeans, dyed back to night', 'Bring tired grey-black straight-leg jeans back to a deep washed black with fabric dye, then refresh the hem.', 'Streetwear', 'Beginner', 2, 'jeans', '#3a3a3d', '#222226', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Old black jeans', 'Black fabric dye', 'Salt']::text[], array['Wash the jeans and weigh them to work out how much dye you need.', 'Dye in a hot bath, stirring often, then rinse until the water runs clear.', 'Let down or re-press the hem so the legs break cleanly over your shoes.']::text[], '/explore/photos/redyed-black-jeans.jpg', 400, 543, 557, 3, '2026-10-01T09:00:00.000Z'),
  ('lace-bell-sleeves', 'flora.fixes', 'Lace bell sleeves for a plain jersey tunic', 'Swap the sleeves of an empire-waist jersey top for flared lace ones cut from a thrifted lace dress.', 'Cottagecore', 'Intermediate', 3, 'blouse', '#3a3f5c', '#2f3550', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Jersey tunic', 'Thrifted lace dress', 'Ballpoint needle']::text[], array['Unpick the original sleeves and use one as a pattern.', 'Cut new sleeves from the lace, flaring the lower half into a bell.', 'Set the lace sleeves in with a stretch stitch and leave the scalloped edge as the hem.']::text[], '/explore/photos/lace-bell-sleeves.jpg', 400, 745, 612, 4, '2026-10-01T08:00:00.000Z'),
  ('floral-puff-mini', 'jo.rebuilt', 'A vintage floral mini with smocked puff sleeves', 'Recut a long floral chiffon dress into a lined mini with shirred puff sleeves and a frilled stand collar.', 'Vintage', 'Advanced', 5, 'dress', '#b07a3e', '#c84a4a', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Floral chiffon dress', 'Elastic thread', 'Microtex needle']::text[], array['Shorten the dress, saving enough length for the frill and lining.', 'Shirr each sleeve end with three rows of elastic thread.', 'Gather a narrow frill and sew it into the neckline as a stand collar.']::text[], '/explore/photos/floral-puff-mini.jpg', 400, 490, 668, 5, '2026-10-01T07:00:00.000Z'),
  ('leggings-bralette', 'suki.stitches', 'A triangle bralette from worn-out leggings', 'Cut the good upper-leg fabric from leggings with thin knees into a lined triangle bralette with skinny straps.', 'Y2K', 'Beginner', 1.5, 'cami', '#1c1c1e', '#1c1c1e', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Old leggings', 'Elastic', 'Ballpoint needle']::text[], array['Cut two lined triangles and a 5 cm band from the upper legs.', 'Sew each triangle right sides together, turn, and attach them to the folded band.', 'Make thin straps from the seam edges and cross them at the back.']::text[], '/explore/photos/leggings-bralette.jpg', 400, 543, 389, 6, '2026-10-01T06:00:00.000Z'),
  ('thumbhole-thermal', 'olive.thread', 'Thumbhole cuffs for a stretched-out thermal', 'Swap baggy, worn sleeve ends for long ribbed cuffs with a thumb opening, cut from a darker knit.', 'Minimalist', 'Beginner', 1, 'longsleeve', '#5a5a3e', '#2f3a2e', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Waffle thermal', 'Rib-knit scraps', 'Ballpoint needle']::text[], array['Cut each sleeve 4 cm above the stretched-out edge.', 'Sew rib-knit tubes, leaving a 3 cm gap in the seam for your thumb.', 'Stretch the cuffs to fit the sleeves and attach with a stretch stitch.']::text[], '/explore/photos/thumbhole-thermal.jpg', 400, 602, 412, 7, '2026-10-01T05:00:00.000Z'),
  ('fleece-lined-puffer', 'max.makes', 'Lining a thin puffer hood with an old fleece', 'Hand-sew a cut-up fleece into the hood and sleeve ends of a lightweight puffer, then add fleece thumbhole cuffs.', 'Streetwear', 'Advanced', 5, 'jacket', '#1e1f24', '#d0683a', array['Needle and thread', 'Fabric scissors', 'Iron', 'Measuring tape']::text[], array['Lightweight puffer', 'Old fleece', 'Hand-sewing needle']::text[], array['Trace the hood lining onto the fleece and cut it with a 1 cm allowance.', 'Turn the edges under and slip-stitch the fleece inside the hood, catching only the inner shell.', 'Sew fleece tubes into thumbhole cuffs and tack them inside each sleeve end.']::text[], '/explore/photos/fleece-lined-puffer.jpg', 400, 430, 1204, 0, '2026-10-01T04:00:00.000Z'),
  ('cropped-zip-hoodie', 'leah.loop', 'Crop a zip hoodie, reuse the hem as the band', 'Shorten an oversized zip hoodie to a boxy crop, moving the original ribbed hem band up so it still looks factory-finished.', 'Streetwear', 'Beginner', 2, 'hoodie', '#bdbdbf', '#e7a3c3', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Zip hoodie', 'Stretch thread', 'Zipper stop']::text[], array['Unpick the ribbed hem band and set it aside.', 'Try on, mark the new length, and shorten the zip with a new stop.', 'Sew the ribbed band back on with a stretch stitch, easing the body to fit.']::text[], '/explore/photos/cropped-zip-hoodie.jpg', 400, 542, 671, 1, '2026-10-01T03:00:00.000Z'),
  ('empire-pintuck-blouse', 'bea.reclaimed', 'An oversized shirt, pintucked into a babydoll', 'Pintuck the front yoke of an oversized shirt and gather the body into a high empire seam for a soft babydoll shape.', 'Vintage', 'Intermediate', 4, 'blouse', '#e9e1d2', '#e9e1d2', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Oversized shirt', 'Matching thread', 'Edgestitch foot']::text[], array['Mark eight pintucks either side of the placket, down to just under the bust.', 'Stitch the tucks, then cut the shirt across under the bust.', 'Gather the lower body and rejoin it to the tucked yoke.']::text[], '/explore/photos/empire-pintuck-blouse.jpg', 400, 650, 932, 2, '2026-10-01T02:00:00.000Z'),
  ('shirt-dress-tie', 'studio.sana', 'A boyfriend shirt, lengthened into a tie-front dress', 'Extend an oversized shirt with a matching skirt panel and turn the spare fabric into a knotted front tie.', 'Minimalist', 'Intermediate', 4, 'dress', '#7f8f9a', '#6c7b86', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Oversized shirt', 'Matching crepe or second shirt', 'Waist elastic']::text[], array['Cut the shirt at the natural waist and add a skirt panel cut from a second shirt or crepe.', 'Sew an elastic casing along the waist seam so the bodice blouses over it.', 'Cut two long ties from the leftover fabric and sew them into the front waist seam.']::text[], '/explore/photos/shirt-dress-tie.jpg', 400, 543, 461, 3, '2026-10-01T01:00:00.000Z'),
  ('fair-isle-crop', 'ria.remix', 'A shrunken sweater’s yoke on a slub tee', 'Save the patterned yoke of a felted Fair Isle sweater and join it to a fitted slub tee with a lettuce-edge hem.', 'Y2K', 'Intermediate', 2.5, 'crop', '#7f7fbf', '#d96aa8', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Fair Isle sweater', 'Slub-knit tee', 'Stretch thread']::text[], array['Cut the sweater straight across below the yoke pattern and zigzag the edge.', 'Cut the tee to match and join the two with a stretch stitch, easing the knit.', 'Stretch the hem as you zigzag over it for a lettuce edge.']::text[], '/explore/photos/fair-isle-crop.jpg', 400, 534, 873, 4, '2026-10-01T00:00:00.000Z'),
  ('pintuck-floral-shirt', 'fin.repairs', 'Pintucks on a thrifted ’70s floral shirt', 'Turn a boxy vintage-print shirt into a soft oversized blouse with a pintucked front and gathered cuffs.', 'Vintage', 'Intermediate', 3, 'shirt', '#8e3b33', '#a9b9b5', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Floral button-up', 'Matching thread', 'Edgestitch foot']::text[], array['Mark six vertical pintuck lines on each side of the button placket.', 'Fold and stitch each tuck 3 mm from the fold, then press toward the side seams.', 'Gather the sleeve ends into narrow cuffs so they push up easily.']::text[], '/explore/photos/pintuck-floral-shirt.jpg', 400, 600, 594, 5, '2026-09-30T23:00:00.000Z'),
  ('twist-front-top', 'eden.edits', 'A twist front for a plain long-sleeve tee', 'Turn a basic black jersey long-sleeve into a sleek V-neck with a twisted knot at the center front.', 'Minimalist', 'Intermediate', 2, 'longsleeve', '#1d1d20', '#1d1d20', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Jersey long-sleeve tee', 'Jersey scraps', 'Ballpoint needle']::text[], array['Cut a deep V down the center front, stopping just below the bust.', 'Pleat each side of the V and twist the two halves once around each other.', 'Stitch the twist on the inside and bind the neckline with a jersey strip.']::text[], '/explore/photos/twist-front-top.jpg', 400, 548, 742, 6, '2026-09-30T22:00:00.000Z'),
  ('lace-inset-blouse', 'mae.mends', 'Grandma’s lace, set into a peasant blouse', 'Set bands of vintage lace across the body and sleeves of a plain cotton blouse, then finish with a ruffled tie neck.', 'Cottagecore', 'Intermediate', 3, 'blouse', '#efe9de', '#f6f1e6', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Cotton blouse', 'Vintage lace trim', 'Narrow ribbon']::text[], array['Mark two bands across the bodice and one around each sleeve.', 'Pin lace over each band, stitch both edges, then cut away the fabric behind.', 'Gather a fabric strip into a ruffle for the neckline and add ribbon ties.']::text[], '/explore/photos/lace-inset-blouse.jpg', 400, 442, 527, 7, '2026-09-30T21:00:00.000Z'),
  ('barrel-leg-cargos', 'alex.alters', 'Straight cargos, re-cut into barrel legs', 'Give straight-leg cargo pants a curved barrel shape with knee darts, a drawstring waist, and gathered ankles.', 'Minimalist', 'Intermediate', 3.5, 'trousers', '#a3a68a', '#1d1d1f', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Cargo pants', 'Cotton drawcord', 'Narrow elastic']::text[], array['Unpick the outseams from hip to hem and mark a curve that bows out at the knee.', 'Sew two darts at each knee, then resew the outseams along the new curve.', 'Thread a drawcord through the waistband and elastic through the ankle hems.']::text[], '/explore/photos/barrel-leg-cargos.jpg', 400, 602, 1036, 0, '2026-09-30T20:00:00.000Z'),
  ('rolled-sleeve-tee', 'dk.threads', 'A boxy grey tee with sleeves that stay rolled', 'Give a soft, worn-in tee a cleaner shape with permanently cuffed sleeves and a slightly cropped, boxy hem.', 'Minimalist', 'Beginner', 0.5, 'tee', '#8a8a88', '#6e6e6c', array['Needle and thread', 'Fabric scissors', 'Iron', 'Measuring tape']::text[], array['Cotton tee', 'Matching thread', 'Twin needle']::text[], array['Fold each sleeve up twice to the length you like and press.', 'Hand-tack the cuff at the shoulder and underarm seams so it never unrolls.', 'Take 3 cm off the hem and finish it with a twin needle.']::text[], '/explore/photos/rolled-sleeve-tee.jpg', 400, 534, 284, 1, '2026-09-30T19:00:00.000Z'),
  ('camp-tee-crop', 'evo.mends', 'An old camp tee, cut boxy and short', 'Turn an oversized summer-camp tee into a boxy, slightly cropped fit without losing the graphic.', 'Streetwear', 'Beginner', 1, 'tee', '#efefed', '#2a4a9a', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Graphic tee', 'Ballpoint needle', 'Stretch thread']::text[], array['Lay a tee you like on top and trace its shoulder width and length.', 'Take in the side seams from underarm to hem, keeping the print centered.', 'Hem with a narrow zigzag so the knit still stretches.']::text[], '/explore/photos/camp-tee-crop.jpg', 400, 534, 203, 2, '2026-09-30T18:00:00.000Z'),
  ('pocket-patch-tee', 'lib.stitch', 'A chest pocket from the hem you cut off', 'Shorten a long white tee and turn the leftover hem into a neat chest pocket.', 'Minimalist', 'Beginner', 1, 'tee', '#f1f1ef', '#1c1c1c', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['White tee', 'Matching thread', 'Fabric chalk']::text[], array['Cut 6 cm off the hem and keep the strip.', 'Fold the strip into a 10 cm square pocket with the original hem as its top edge.', 'Topstitch the pocket on the left chest and re-hem the shirt.']::text[], '/explore/photos/pocket-patch-tee.jpg', 400, 534, 177, 3, '2026-09-30T17:00:00.000Z'),
  ('chino-cutoffs', 'hokie.hemlines', 'Too-short chinos, made into cutoff shorts', 'Cut chinos that are too short into relaxed shorts with a clean rolled hem.', 'Streetwear', 'Beginner', 0.5, 'trousers', '#b9b5a8', '#f4f4f2', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Old chinos', 'Fabric scissors', 'Matching thread']::text[], array['Try on and mark a length 4 cm below where you want the shorts to end.', 'Cut both legs evenly and overlock or zigzag the raw edges.', 'Fold the hem up twice and tack the roll at the side seams.']::text[], '/explore/photos/chino-cutoffs.jpg', 400, 534, 318, 4, '2026-09-30T16:00:00.000Z'),
  ('cream-hoodie-hem', 'charlie.kirk', 'A split hem for an oversized cream hoodie', 'Take out the tight ribbed waistband of an oversized hoodie and replace it with a relaxed split hem.', 'Minimalist', 'Beginner', 1, 'hoodie', '#ece6da', '#d9cfc0', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Oversized hoodie', 'Matching thread', 'Seam ripper']::text[], array['Unpick or cut off the ribbed waistband.', 'Mark 8 cm side slits and fold the edges under as narrow facings.', 'Topstitch the hem and slits, then bar-tack the top of each slit.']::text[], '/explore/photos/cream-hoodie-hem.jpg', 400, 534, 446, 5, '2026-09-30T15:00:00.000Z'),
  ('cardigan-wrap-top', 'ana.alters', 'A black cardigan, rebuilt as a wrap top', 'Remove the buttons from a fine-knit cardigan and reshape the fronts into a wrap top with ties.', 'Minimalist', 'Intermediate', 2.5, 'cardigan', '#1f1f22', '#2a2a2d', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Fine-knit cardigan', 'Jersey binding', 'Snap fastener']::text[], array['Remove the buttons and close the buttonholes with a few hand stitches.', 'Cut the fronts on a diagonal from neckline to hem and bind the edges.', 'Add long ties from the cut-off fabric and a hidden snap at the waist.']::text[], '/explore/photos/cardigan-wrap-top.jpg', 400, 534, 529, 6, '2026-09-30T14:00:00.000Z'),
  ('college-hoodie-patches', 'ben.repairs', 'Denim elbow patches for a well-loved college hoodie', 'Cover worn-through hoodie elbows with oval patches cut from old denim.', 'Vintage', 'Beginner', 1.5, 'hoodie', '#6b1f2e', '#d9a066', array['Needle and thread', 'Fabric scissors', 'Iron', 'Measuring tape']::text[], array['College hoodie', 'Denim scraps', 'Embroidery floss']::text[], array['Try on the hoodie and mark the elbow wear with chalk.', 'Cut two denim ovals, fold the edges under, and pin them over the marks.', 'Hand-sew them on with a blanket stitch, keeping your other hand inside the sleeve.']::text[], '/explore/photos/college-hoodie-patches.jpg', 400, 534, 612, 7, '2026-09-30T13:00:00.000Z'),
  ('sleeve-balaclava', 'min.knit', 'A knit balaclava from a sweater sleeve', 'Use the wide sleeve of a ribbed sweater to make a snug balaclava for cold mornings.', 'Streetwear', 'Intermediate', 2, null, '#1b1b1d', '#1b1b1d', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Ribbed sweater', 'Stretch thread', 'Ballpoint needle']::text[], array['Cut the sleeve off at the shoulder and try it on as a tube over your head.', 'Cut the face opening and bind it with the sweater’s cuff ribbing.', 'Close the top with a curved seam and finish with a stretch stitch.']::text[], '/explore/photos/sleeve-balaclava.jpg', 400, 375, 734, 0, '2026-09-30T12:00:00.000Z'),
  ('boxy-tee-recut', 'joon.sews', 'An oversized tee, recut to a clean boxy fit', 'Shorten the sleeves and body of a too-long tee for a heavyweight, boxy shape.', 'Minimalist', 'Beginner', 1.5, 'tee', '#f2f2f0', '#e2e2e0', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Oversized tee', 'Twin needle', 'Fabric chalk']::text[], array['Trace a favorite boxy tee onto the oversized one.', 'Cut the new side seams, then shorten the sleeves to just above the elbow.', 'Sew with a stretch stitch and twin-needle the hems.']::text[], '/explore/photos/boxy-tee-recut.jpg', 400, 418, 398, 1, '2026-09-30T11:00:00.000Z'),
  ('dip-dyed-waffle-hoodie', 'haru.dyes', 'A sun-faded waffle hoodie, dip-dyed teal', 'Revive a faded waffle-knit hoodie with an even teal dye bath.', 'Streetwear', 'Beginner', 1.5, 'hoodie', '#6aa5b3', '#1f3a52', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Waffle hoodie', 'Fabric dye', 'Salt']::text[], array['Wash the hoodie and weigh it to work out how much dye you need.', 'Dye it in a warm bath, stirring often, for an even color.', 'Rinse until the water runs clear, then wash it on its own.']::text[], '/explore/photos/dip-dyed-waffle-hoodie.jpg', 400, 396, 857, 2, '2026-09-30T10:00:00.000Z'),
  ('crew-to-henley', 'theo.knits', 'A crewneck sweater, turned henley', 'Cut a short button placket into a crewneck sweater for a relaxed henley neckline.', 'Minimalist', 'Advanced', 3, 'longsleeve', '#7a6b5d', '#e8e4dc', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Crewneck sweater', 'Fusible tape', 'Three buttons']::text[], array['Stabilize a 12 cm line down the center front with fusible tape.', 'Cut the slit and bind both sides with a woven placket strip.', 'Sew three buttonholes and buttons, then press the placket flat.']::text[], '/explore/photos/crew-to-henley.jpg', 400, 426, 492, 3, '2026-09-30T09:00:00.000Z'),
  ('windbreaker-hood', 'kai.outdoor', 'A packable hood for a nylon windbreaker', 'Add a hood that rolls into the collar of a hoodless windbreaker, using nylon from an old rain shell.', 'Streetwear', 'Intermediate', 3, 'jacket', '#1a1a1c', '#e9e9e9', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Windbreaker', 'Old rain shell', 'Snap tape']::text[], array['Draft a hood from a hoodie you own and cut it from the spare nylon.', 'Sew the hood seams with French seams so nothing frays.', 'Attach it inside the collar with a zip or snaps so it rolls away.']::text[], '/explore/photos/windbreaker-hood.jpg', 400, 418, 403, 4, '2026-09-30T08:00:00.000Z'),
  ('leather-racer-collar', 'seo.leather', 'A blazer-collar leather jacket, re-cut as a racer', 'Remove the lapels from a thrifted leather jacket and finish the neckline with a short band collar.', 'Vintage', 'Advanced', 6, 'jacket', '#202022', '#3a3a3d', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Leather jacket', 'Leather needle', 'Leather tape']::text[], array['Unpick the collar and mark a new band collar line.', 'Cut a band from the lapel leather and glue-baste it in place with leather tape.', 'Sew with a leather needle and a long stitch, then edge the neckline.']::text[], '/explore/photos/leather-racer-collar.jpg', 400, 414, 1124, 5, '2026-09-30T07:00:00.000Z'),
  ('pleated-wide-trousers', 'yun.tailor', 'Slim suit trousers with new pleats and a wider hem', 'Give fitted wool trousers a softer look with front pleats and a let-down hem.', 'Minimalist', 'Intermediate', 3.5, 'trousers', '#5f6670', '#9fb0b2', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Wool trousers', 'Matching thread', 'Hem tape']::text[], array['Unpick the waistband across the front.', 'Fold two pleats on each side and baste them at the waist.', 'Reattach the waistband and let down the hem to full length.']::text[], '/explore/photos/pleated-wide-trousers.jpg', 400, 427, 567, 6, '2026-09-30T06:00:00.000Z'),
  ('caped-wool-coat', 'yeon.remake', 'A capelet made from your coat’s cut-off hem', 'Shorten a long wool coat and turn the cut-off length into a detachable capelet with covered buttons.', 'Cottagecore', 'Advanced', 6, 'jacket', '#f1ece2', '#e8e0d2', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Long wool coat', 'Lining fabric', 'Covered buttons']::text[], array['Shorten the coat and keep the full width of the removed hem.', 'Cut a half-circle capelet and line it with the coat’s spare lining.', 'Add buttonholes so it buttons onto the coat collar.']::text[], '/explore/photos/caped-wool-coat.jpg', 400, 411, 978, 7, '2026-09-30T05:00:00.000Z'),
  ('tulle-tier-skirt', 'hana.tulle', 'Old petticoat tulle, made into a tiered ballet skirt', 'Gather layers of tulle from an old petticoat into a full tiered mini with a ribbon bow.', 'Y2K', 'Intermediate', 3, 'skirt', '#f3efeb', '#f2c9d3', array['Sewing machine', 'Fabric scissors', 'Pins or clips', 'Iron', 'Measuring tape']::text[], array['Petticoat tulle', 'Waist elastic', 'Satin ribbon']::text[], array['Cut three tulle tiers, each one and a half times wider than the last.', 'Gather each tier and sew them onto a soft knit base.', 'Add an elastic waistband and a ribbon bow at the front.']::text[], '/explore/photos/tulle-tier-skirt.jpg', 400, 423, 841, 0, '2026-09-30T04:00:00.000Z')
